export function formatToolResults(
  results: Array<{ tool: string; status: "ok" | "error"; output: string }>,
): string {
  const parts = results.map(
    (r, i) =>
      `<glint:result n="${i + 1}" tool="${r.tool}" status="${r.status}">\n${r.output}\n</glint:result>`,
  );
  const failures = results.filter((r) => r.status === "error").length;
  const warning =
    failures > 0
      ? `\n\n⚠ ${failures} tool call(s) FAILED. Read the error, fix the cause, retry. Do NOT claim success while any required action failed.`
      : "";
  return `[tool results]\n${parts.join("\n")}${warning}`;
}
